#!/usr/bin/env bash
# Write conf/main.conf and conf/http.conf from the app's settings; nginx.conf
# includes them. nginx.conf, conf.d/ and the websites in sites/ are kept.
. "$(dirname "$0")/lib.sh"
state_load

for d in conf conf.d sites ssl www acme logs temp run; do
  mkdir -p "$APP_DIR/$d"
done
# Workers of a root master would run as nobody; keep them able to read html/.
user=""
is_root && user="user root;"

write_file "$APP_DIR/conf/main.conf" <<CONF
# Generated by XDeck from the app's settings; changes here are overwritten.
$user
worker_processes auto;
error_log stderr warn;
CONF

write_file "$APP_DIR/conf/http.conf" <<CONF
# Generated by XDeck from the app's settings; changes here are overwritten.
access_log /dev/stdout;
client_body_temp_path temp/client_body;
proxy_temp_path temp/proxy;
fastcgi_temp_path temp/fastcgi;
uwsgi_temp_path temp/uwsgi;
scgi_temp_path temp/scgi;

server {
    listen ${BIND:-0.0.0.0}:${PORT:-8080};
    server_name _;
    root html;
    index index.html;

    location / {
        try_files \$uri \$uri/ =404;
    }
}
CONF

# Installations before 1.30-1 kept everything in conf/.
rm -f "$APP_DIR/conf/nginx.conf"

flags=(-p "$APP_DIR/" -c nginx.conf)
[ "$NGINX_ERROR_LOG_FLAG" = 1 ] && flags+=(-e stderr)
"$NGINX_BIN" "${flags[@]}" -t
